svg.script:
// 
(function () {
  var svg = document.querySelector('svg');
  if (!svg) return;

  // Mode switch — reads ?mode= param and applies CSS class + inline fallback
  var MODES = {
    'dark': {'--logo-primary':'#E2E8F0','--logo-secondary':'#F8FAFC','--logo-accent':'#CBD5E1','--logo-disc':'#94A3B8','--logo-disc-highlight':'#CBD5E1','--logo-vinyl':'#64748B','--logo-vinyl-groove':'#7A8A9E','--logo-vinyl-groove-alt':'#94A3B8','--logo-shadow':'rgba(0,0,0,0.7)','--logo-glow':'rgba(226,232,240,0.15)'},
    'cb-deutan': {'--logo-primary':'#648FFF','--logo-secondary':'#FFB000','--logo-accent':'#785EF0','--logo-disc':'#7B8FAA','--logo-disc-highlight':'#9BADC4','--logo-vinyl':'#5A6E87','--logo-vinyl-groove':'#6A7E97','--logo-vinyl-groove-alt':'#7B8FAA'},
    'cb-protan': {'--logo-primary':'#648FFF','--logo-secondary':'#DC267F','--logo-accent':'#FFB000','--logo-disc':'#7B8FAA','--logo-disc-highlight':'#9BADC4','--logo-vinyl':'#5A6E87','--logo-vinyl-groove':'#6A7E97','--logo-vinyl-groove-alt':'#7B8FAA'},
    'cb-tritan': {'--logo-primary':'#D55E00','--logo-secondary':'#CC79A7','--logo-accent':'#D55E00','--logo-disc':'#7B8FAA','--logo-disc-highlight':'#9BADC4','--logo-vinyl':'#5A6E87','--logo-vinyl-groove':'#6A7E97','--logo-vinyl-groove-alt':'#7B8FAA'},
    'cb-deutan-dark': {'--logo-primary':'#85AAFF','--logo-secondary':'#FFC940','--logo-accent':'#9B85FF','--logo-disc':'#8A9AB5','--logo-disc-highlight':'#B8C5D8','--logo-vinyl':'#5A6A82','--logo-vinyl-groove':'#6E7E96','--logo-vinyl-groove-alt':'#8A9AB5','--logo-shadow':'rgba(0,0,0,0.7)'},
    'cb-protan-dark': {'--logo-primary':'#85AAFF','--logo-secondary':'#FF5CA1','--logo-accent':'#FFC940','--logo-disc':'#8A9AB5','--logo-disc-highlight':'#B8C5D8','--logo-vinyl':'#5A6A82','--logo-vinyl-groove':'#6E7E96','--logo-vinyl-groove-alt':'#8A9AB5','--logo-shadow':'rgba(0,0,0,0.7)'},
    'cb-tritan-dark': {'--logo-primary':'#FF8533','--logo-secondary':'#E09DBF','--logo-accent':'#FF8533','--logo-disc':'#8A9AB5','--logo-disc-highlight':'#B8C5D8','--logo-vinyl':'#5A6A82','--logo-vinyl-groove':'#6E7E96','--logo-vinyl-groove-alt':'#8A9AB5','--logo-shadow':'rgba(0,0,0,0.7)'}
  };
  try {
    // Try ?mode= query param first, then fall back to #hash
    // (Edge strips query params from file:// SVG URLs, but preserves hashes)
    // Usage: logo.svg?mode=dark  OR  logo.svg#dark
    var search = window.location.search || '';
    var hash = window.location.hash || '';
    var p = new URLSearchParams(search);
    var m = p.get('mode') || hash.replace('#', '') || null;
    if (m && m !== 'light') {
      // Apply CSS class(es)
      if (m.indexOf('-dark') > 0 && m.indexOf('cb-') === 0) {
        svg.classList.add('dark');
        svg.classList.add(m.replace('-dark', ''));
      } else {
        svg.classList.add(m);
      }
      // Also apply as inline styles (fallback for Edge file:// and SVG contexts
      // where class-based custom property overrides don't take effect)
      var props = MODES[m];
      if (props) {
        for (var key in props) {
          svg.style.setProperty(key, props[key]);
        }
      }
    }
  } catch (e) {}

  // Dynamic chevron field generation.
  // Measures the actual rendered area of the SVG element and
  // generates chevron columns/rows to fill it completely,
  // regardless of the container's aspect ratio.
  var NS = 'http://www.w3.org/2000/svg';
  var field = document.getElementById('chevron-field');
  if (!field) return;

  function generateChevrons() {
    // Clear any previously generated chevrons
    while (field.firstChild) field.removeChild(field.firstChild);

    // Get the SVG's rendered size in screen pixels
    var rect = svg.getBoundingClientRect();
    var w = rect.width;
    var h = rect.height;
    if (w === 0 || h === 0) return;

    // The viewBox is 512x512 but the rendered area may differ.
    // Calculate how much extra space exists beyond the viewBox
    // in SVG coordinate units.
    var vb = svg.viewBox.baseVal;
    var vbW = vb.width || 512;
    var vbH = vb.height || 512;

    // Scale factor: how many SVG units per screen pixel
    var scaleX = vbW / w;
    var scaleY = vbH / h;

    // The actual SVG coordinate area visible on screen
    var aspect = w / h;
    var visW, visH, offX, offY;

    if (aspect > 1) {
      // Wider than tall: extra horizontal space
      visH = vbH;
      visW = vbH * aspect;
      offX = vb.x - (visW - vbW) / 2;
      offY = vb.y;
    } else {
      // Taller than wide: extra vertical space
      visW = vbW;
      visH = vbW / aspect;
      offX = vb.x;
      offY = vb.y - (visH - vbH) / 2;
    }

    // Chevron grid parameters (in SVG coordinate units)
    var colSpacing = 50;
    var rowSpacing = 65;
    var chevW = 24;  // width of each V
    var chevH = 18;  // height of each V

    // Generate columns and rows to cover the full visible area
    var cols = Math.ceil(visW / colSpacing) + 2;
    var rows = Math.ceil(visH / rowSpacing) + 2;
    var startX = offX - colSpacing;
    var startY = offY - rowSpacing;

    var delays = [0.00, 0.10, 0.05, 0.15, 0.08, 0.18, 0.12, 0.03, 0.16, 0.07];
    var rowInc = 0.22;

    for (var c = 0; c < cols; c++) {
      var cx = startX + c * colSpacing + colSpacing / 2;
      var baseDelay = delays[c % delays.length];

      for (var r = 0; r < rows; r++) {
        var cy = startY + r * rowSpacing;
        var delay = (baseDelay + r * rowInc) % 1.8;

        var path = document.createElementNS(NS, 'path');
        path.setAttribute('class', 'chev');
        path.setAttribute('d',
          'M' + (cx - chevW / 2) + ',' + cy +
          ' L' + cx + ',' + (cy + chevH) +
          ' L' + (cx + chevW / 2) + ',' + cy
        );
        path.setAttribute('style',
          'animation:chev-fall 1.8s ease-in-out infinite ' + delay.toFixed(2) + 's'
        );
        field.appendChild(path);
      }
    }
  }

  // Generate on load and on resize
  generateChevrons();
  var resizeTimer;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(generateChevrons, 150);
  });
})();
//
